/* UX refinement: searchable borrowers, edition/copy discovery and actionable management. */
const ux={author:'',subject:'',from:'',to:'',edition:0,borrower:'SV20240018',report:'Tổng quan'};
const borrowers=[{id:'SV20240018',name:'Nguyễn Minh Anh',unit:'Công nghệ thông tin',card:db.card,loans:state.loans,history:state.history,holds:state.holds},{id:'SV20240032',name:'Trần Hải Nam',unit:'Kinh tế',card:{status:'Hoạt động',expiry:'2027-06-30',email:'hainam@example.edu',phone:'0911111111'},loans:[],history:[],holds:[]},{id:'SV20230056',name:'Lê Ngọc Linh',unit:'Thiết kế',card:{status:'Bị khóa',expiry:'2026-12-31',email:'ngoclinh@example.edu',phone:'0922222222'},loans:[],history:[],holds:[]}];
const currentBorrower=()=>borrowers.find(p=>p.id===ux.borrower);
// Use one individual-copy collection for public availability, inventory and checkout.
const copies=[];
books.forEach(b=>{b.workId=b.id;b.edition=b.year+' · Bản tiêu chuẩn';if(b.type==='Sách in'){for(let i=0;i<b.copies;i++)copies.push({id:copies.length+1,code:b.code+'-'+String(i+1).padStart(3,'0'),book:b.id,location:b.shelf,status:'Sẵn sàng'});if(state.loans.some(l=>l.id===b.id)){let c={id:copies.length+1,code:b.code+'-'+String(b.copies+1).padStart(3,'0'),book:b.id,location:b.shelf,status:'Đang mượn'};copies.push(c);state.loans.find(l=>l.id===b.id).copyCode=c.code}}});
db.copies=copies;
books.push({id:Math.max(...books.map(b=>b.id))+1,workId:1,edition:'2022 · Ấn bản thứ nhất',title:'Nhập môn trí tuệ nhân tạo',author:'Nguyễn Thanh Bình',year:2022,subject:'Công nghệ thông tin',type:'Sách in',copies:0,shelf:'T2 · A03 · K05',code:'AI-008',color:'#254c67',cover:'Trí tuệ<br>nhân tạo',desc:'Ấn bản trước của cùng tác phẩm, đang được mượn hết trong dữ liệu minh họa.',status:'Đã công bố'});
db.copies.push({id:db.copies.length+1,code:'AI-008-001',book:books.at(-1).id,location:'T2 · A03 · K05',status:'Đang mượn'});
function syncCopies(){books.forEach(b=>{if(b.type==='Sách in')b.copies=db.copies.filter(c=>c.book===b.id&&c.status==='Sẵn sàng').length})}
const style2=document.createElement('style');style2.textContent=`.filtergrid{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:10px;margin-bottom:18px}.filtergrid input,.filtergrid select{width:100%;padding:10px;border:1px solid var(--line);border-radius:6px;background:white}.fineprint{font-size:12px;color:var(--muted)}.metricgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:22px 0}.metric{padding:22px;background:white;border:1px solid var(--line);border-radius:10px}.metric strong{display:block;font-size:32px;letter-spacing:-1px;margin:8px 0}.metric small{font-size:12px;color:var(--muted)}.reportgrid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.statuscards{display:grid;grid-template-columns:1fr 1fr;gap:12px}.statuscard{border:1px solid var(--line);border-left:4px solid var(--blue);padding:16px;border-radius:7px;background:#fbfcfe}.statuscard strong{display:block;font-size:26px;margin:6px 0}.progressrail{height:6px;border-radius:5px;background:#e6edf5;margin-top:12px;overflow:hidden}.progressrail i{display:block;height:100%;background:var(--blue)}.editionlist{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}.editionlist button{text-align:left;min-width:190px}.editionlist button.active{border-color:var(--blue);background:var(--pale)}.editionlist small{display:block;font-weight:400;margin-top:4px}.borrowerlookup{width:100%;padding:10px;border:1px solid #b8cadb;border-radius:6px}.borrowerresult{display:block;text-align:left;width:100%;margin-top:8px;font-size:12px}.tagpreview{padding:24px;border:2px solid #172b46;text-align:center;margin:20px 0}.tagpreview strong{font-family:Consolas,monospace;display:block;font-size:23px}.taskitem{border-bottom:1px solid var(--line);padding:15px 0;display:flex;justify-content:space-between;gap:16px}.taskitem p{margin:3px 0;font-size:12px;color:var(--muted)}.detailsummary{display:grid;grid-template-columns:130px 1fr;gap:12px;margin:20px 0}.detailsummary dt{font-size:13px}.detailsummary dd{font-size:13px}.workpick{border:1px solid var(--line);padding:20px;background:white;border-radius:10px}@media(max-width:1000px){.metricgrid{grid-template-columns:repeat(2,1fr)}.filtergrid{grid-template-columns:1fr 1fr}}@media(max-width:760px){.reportgrid{grid-template-columns:1fr}.filtergrid{grid-template-columns:1fr}.filtergrid[data-column-filters]{grid-template-columns:1fr!important}.statuscards{grid-template-columns:1fr 1fr}}`;document.head.appendChild(style2);
function opts(values,selected,empty='Tất cả'){return `<option value="">${empty}</option>`+values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}
function resetSearch(){state.q='';state.type='';state.only=false;Object.assign(ux,{author:'',subject:'',from:'',to:''});render()}
const previousSearch=views.search;
views.search=function(){let markup=previousSearch();markup=markup.replace('<div class="filterblock"><h3>Địa điểm</h3>',`<div class="filterblock"><h3>Thể loại / Chủ đề</h3><select aria-label="Lọc thể loại" onchange="ux.subject=this.value;results()">${opts([...new Set(books.map(b=>b.subject))],ux.subject)}</select></div><div class="filterblock"><h3>Tác giả</h3><select aria-label="Lọc tác giả" onchange="ux.author=this.value;results()">${opts([...new Set(books.map(b=>b.author))],ux.author)}</select></div><div class="filterblock"><h3>Năm xuất bản</h3><label class="field">Từ năm<input type="number" min="1900" max="2100" value="${ux.from}" oninput="ux.from=this.value;results()"></label><label class="field">Đến năm<input type="number" min="1900" max="2100" value="${ux.to}" oninput="ux.to=this.value;results()"></label></div><div class="filterblock"><h3>Địa điểm</h3>`);markup=markup.replace("state.type='';state.only=false;state.q='';render()","resetSearch()");return markup};
results=function(){syncCopies();let list=books.filter(b=>b.status==='Đã công bố'&&(!state.type||state.type===b.type)&&(!ux.author||ux.author===b.author)&&(!ux.subject||ux.subject===b.subject)&&(!ux.from||b.year>=+ux.from)&&(!ux.to||b.year<=+ux.to)&&(!state.only||b.copies>0||b.type!=='Sách in')&&norm(b.title+' '+b.author+' '+b.code).includes(norm(state.q)));if(state.sort==='new')list.sort((a,b)=>b.year-a.year);if(state.sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title,'vi'));let groups=[...new Set(list.map(b=>b.workId||b.id))];$('#count').innerHTML=`<strong>${groups.length} tác phẩm · ${list.length} ấn bản</strong>`;$('#results').innerHTML=groups.length?groups.map(w=>{let editions=list.filter(b=>(b.workId||b.id)===w),b=editions[0],n=editions.reduce((s,e)=>s+e.copies,0);return `<article class="bookcard"><div class="bookstage"><span class="typeflag">${b.type}</span>${cover(b)}</div><div class="bookbody"><div class="subject">${esc(b.subject)}</div><button class="titlebutton" onclick="openBook(${b.id})">${esc(b.title)}</button><div class="author">${esc(b.author)} · ${b.year}</div><div class="availability ${!n&&b.type==='Sách in'?'wait':''}">${b.type!=='Sách in'?'Có toàn văn':n?'Còn '+n+' bản sẵn sàng':'Hết bản sẵn sàng · Có thể đặt trước'}</div><div class="shelf"><span>${editions.length} ấn bản phù hợp</span><button class="link small" onclick="openBook(${b.id})">Xem vị trí →</button></div></div></article>`}).join(''):`<div class="empty full"><h3>Không có tài liệu phù hợp</h3><p>Thử bỏ bớt điều kiện hoặc kiểm tra khoảng năm.</p><button onclick="resetSearch()">Xóa tất cả bộ lọc</button></div>`};
const prevDetail=views.detail;
views.detail=function(){syncCopies();let b=book(state.selected);if(b.type!=='Sách in')return prevDetail()+related(b);let editions=books.filter(e=>(e.workId||e.id)===(b.workId||b.id)&&e.status==='Đã công bố');if(!editions.includes(b))return prevDetail();let list=db.copies.filter(c=>c.book===b.id),count=editions.reduce((s,e)=>s+e.copies,0),reserved=state.holds.some(h=>h.id===b.id);return `<div class="wrap"><button class="link back" onclick="go('search')">← Kết quả tìm kiếm</button><div class="detailgrid"><div>${cover(b)}</div><section><div class="eyebrow">${esc(b.subject)} · ${b.type}</div><h1>${esc(b.title)}</h1><p class="muted">${esc(b.author)}</p><p>${esc(b.desc)}</p><p><strong>${editions.length} ấn bản</strong> · ${count} bản sẵn sàng trong toàn bộ ấn bản</p></section><aside class="panel"><h3>Ấn bản đang chọn</h3><p>${esc(b.edition||b.year+' · Bản tiêu chuẩn')}</p>${badge(b.copies?'Còn '+b.copies+' bản':'Hết bản sẵn sàng',b.copies?'':'warn')}<p class="fineprint" style="margin-top:15px">Đặt trước áp dụng cho ấn bản đang chọn, không gắn vào một mã cuốn cụ thể.</p>${b.copies?btn('Xem bản sao trên kệ',"document.getElementById('editioncopies').scrollIntoView({behavior:'smooth'})",true):`<button class="primary" ${reserved?'disabled':''} onclick="hold(${b.id})">${reserved?'Đã đặt trước':session.role?'Đặt trước ấn bản này':'Đăng nhập để đặt trước'}</button>`}</aside></div><section class="panel" id="editioncopies" style="margin-top:30px"><h2>Ấn bản và bản sao</h2><div class="editionlist">${editions.map(e=>`<button class="${e.id===b.id?'active':''}" onclick="openBook(${e.id})">${esc(e.edition||e.year+' · Bản tiêu chuẩn')}<small>${e.copies} sẵn sàng / ${db.copies.filter(c=>c.book===e.id).length} bản · ${e.code}</small></button>`).join('')}</div>${table(['Mã cuốn','Cơ sở','Vị trí cụ thể','Trạng thái','Hành động'],list.map(c=>[esc(c.code),'Cơ sở A',esc(locationLabel(c.location)),badge(c.status,c.status==='Sẵn sàng'?'':c.status==='Đang mượn'?'warn':'gray'),c.status==='Sẵn sàng'?'Đến kệ lấy sách, làm thủ tục tại quầy':'Chọn đặt trước ở khối bên trên']))}${!list.length?'<p class="muted">Ấn bản này chưa có bản sao được nhập kho.</p>':''}</section>${related(b,false)}</div>`};
function locationLabel(s){return s.replace(/T(\d+)/g,'Tầng $1').replace(/A(\d+)/g,'Dãy A$1').replace(/B(\d+)/g,'Dãy B$1').replace(/K(\d+)/g,'Kệ $1')}
function related(b,wrap=true){let other=books.filter(x=>x.status==='Đã công bố'&&x.subject===b.subject&&(x.workId||x.id)!==(b.workId||b.id)).slice(0,3);return `<section class="${wrap?'wrap':'panel'}" style="margin-top:24px"><h2>Có thể bạn cũng quan tâm</h2><p class="muted">Tài liệu cùng chủ đề ${esc(b.subject)}</p><div class="tiles">${other.length?other.map(x=>`<article class="tile"><div class="eyebrow">${x.type} · ${x.year}</div><h3 style="margin-top:12px">${esc(x.title)}</h3><p>${esc(x.author)}</p>${btn('Xem tài liệu',`openBook(${x.id})`)}</article>`).join(''):'<p class="muted">Chưa có tài liệu cùng chủ đề khác trong bộ dữ liệu mẫu.</p>'}</div></section>`}
views.desk=function(){let p=currentBorrower(),out=state.deskTab==='out';return shell('Quầy mượn trả','Tìm đúng bạn đọc, chọn bản sao và kiểm tra điều kiện trước khi xác nhận.',`<div class="tabs">${[['out','Cho mượn'],['in','Nhận trả']].map(([v,t])=>`<button class="${state.deskTab===v?'active':''}" onclick="state.deskTab='${v}';state.scanned=[];render()">${t}</button>`).join('')}</div><div class="deskgrid"><aside class="panel"><h3>Tra cứu sinh viên / bạn đọc</h3><input class="borrowerlookup" aria-label="Tìm người mượn" placeholder="Tên, mã sinh viên hoặc email" oninput="findBorrower(this.value)"><div id="borrowerresults"></div><div class="borrower"><div class="avatar">${p.name.split(' ').slice(-2).map(s=>s[0]).join('')}</div><div><strong>${p.name}</strong><div class="fineprint">${p.id} · ${p.unit}</div></div></div>${badge(p.card.status,p.card.status==='Hoạt động'?'':'warn')}<dl class="detailsummary"><dt>Hạn thẻ</dt><dd>${p.card.expiry}</dd><dt>Đang mượn</dt><dd>${p.loans.length} / 5 cuốn</dd><dt>Liên hệ</dt><dd>${p.card.email}</dd></dl>${btn('Xem hồ sơ và khoản mượn',`borrowerDetail('${p.id}')`)}<div class="note">Đổi người mượn sẽ xóa danh sách đang quét để tránh lập nhầm phiếu.</div></aside><section class="panel"><h2>${out?'Sách cho mượn':'Sách nhận trả'}</h2><form class="scan" onsubmit="event.preventDefault();scan(this.elements.code.value)"><input name="code" id="barcode" required aria-label="Quét mã cuốn" placeholder="Nhập mã cuốn AI-001-001 hoặc mã AI-001"><button>Thêm vào phiếu</button></form><p class="fineprint" style="margin:12px 0">Mã thử: ${out?'AI-001-001, TD-006-001':p.loans.map(l=>l.copyCode||book(l.id).code).join(', ')||'Bạn đọc chưa có khoản mượn'}</p>${table(['Bản sao','Tài liệu','Kết quả kiểm tra',''],state.scanned.map(code=>{let c=db.copies.find(x=>x.code===code);return [code,esc(book(c.book).title),badge(out?'Sẵn sàng cho mượn':'Khớp khoản mượn'),btn('Bỏ',`state.scanned=state.scanned.filter(x=>x!=='${code}');render()`)]}))}<div class="actions"><span class="fineprint" style="margin-right:auto">${state.scanned.length} cuốn · ${p.name}</span><button class="primary" ${!state.scanned.length?'disabled':''} onclick="commitDesk()">${out?'Xác nhận cho mượn':'Xác nhận nhận trả'}</button></div></section></div>`)};
function findBorrower(q){let found=borrowers.filter(p=>norm(p.name+' '+p.id+' '+p.card.email).includes(norm(q)));$('#borrowerresults').innerHTML=found.length?found.map(p=>`<button class="borrowerresult" onclick="ux.borrower='${p.id}';state.scanned=[];render()"><strong>${p.name}</strong><br>${p.id} · ${p.unit}</button>`).join(''):'<p class="fineprint">Không tìm thấy bạn đọc. Kiểm tra lại tên hoặc mã.</p>'}
function borrowerDetail(id){let p=borrowers.find(x=>x.id===id),d=$('#dialog');d.innerHTML=`<h2>${p.name}</h2><p>${p.id} · ${p.unit}</p>${badge(p.card.status,p.card.status==='Hoạt động'?'':'warn')}<h3 style="margin-top:20px">Các khoản mượn</h3>${table(['Tài liệu','Mã cuốn','Hạn trả'],p.loans.map(l=>[esc(book(l.id).title),l.copyCode||'—',l.due]))}<div class="actions">${btn('Đóng',"$('#dialog').close()")}</div>`;d.showModal()}
scan=function(code){let p=currentBorrower(),out=state.deskTab==='out',v=String(code||$('#barcode').value).trim().toUpperCase();let c=db.copies.find(x=>x.code===v);if(!c){let b=books.find(x=>x.code===v);if(b)c=db.copies.find(x=>x.book===b.id&&(out?x.status==='Sẵn sàng':p.loans.some(l=>l.copyCode===x.code)))}if(!c)return toast('Không tìm thấy bản sao phù hợp. Kiểm tra mã cuốn.');if(state.scanned.includes(c.code))return toast('Bản sao đã có trong phiếu.');if(out){if(c.status!=='Sẵn sàng')return toast('Bản sao không sẵn sàng để cho mượn.');if(p.card.status!=='Hoạt động')return toast('Thẻ bạn đọc bị khóa.');if(p.loans.length+state.scanned.length>=5)return toast('Đã đạt hạn mức mượn.')}else if(!p.loans.some(l=>l.copyCode===c.code))return toast('Bản sao không thuộc khoản mượn đang mở của bạn đọc đã chọn.');state.scanned.push(c.code);render();$('#barcode').focus()};
commitDesk=function(){if(session.role!=='circulation')return toast('Cần quyền mượn trả.');let p=currentBorrower(),out=state.deskTab==='out';if(!state.scanned.length)return;if(out&&(p.card.status!=='Hoạt động'||p.loans.length+state.scanned.length>5))return toast('Bạn đọc không đủ điều kiện mượn.');let selected=state.scanned.map(code=>db.copies.find(c=>c.code===code));if(selected.some(c=>!c||(out?c.status!=='Sẵn sàng':!p.loans.some(l=>l.copyCode===c.code))))return toast('Dữ liệu đã thay đổi. Vui lòng quét lại.');selected.forEach(c=>{if(out){p.loans.push({id:c.book,copyCode:c.code,due:'20/11/2026',renew:0});c.status='Đang mượn'}else{p.loans.splice(p.loans.findIndex(l=>l.copyCode===c.code),1);p.history.push(c.book);c.status='Sẵn sàng'}});log((out?'Cho mượn':'Nhận trả')+' '+selected.length+' bản · '+p.id);state.scanned=[];
syncCopies();render();
toast('Đã cập nhật giao dịch của '+p.name)};
views.patrons=function(){return shell('Bạn đọc và thẻ','Tra cứu thông tin, tình trạng thẻ và từng khoản mượn.',`<section class="panel">${filterBar(['Tất cả trạng thái','Hoạt động','Bị khóa'])}${table(['Bạn đọc','Đơn vị','Trạng thái','Hạn thẻ','Đang mượn','Thao tác'],borrowers.map(p=>[p.name+'<br><small>'+p.id+'</small>',p.unit,badge(p.card.status,p.card.status==='Hoạt động'?'':'warn'),p.card.expiry,p.loans.length,btn('Chi tiết',`borrowerDetail('${p.id}')`)+btn('Sửa thẻ',`editBorrowerCard('${p.id}')`)+btn('Chọn tại quầy',`ux.borrower='${p.id}';state.scanned=[];go('desk')`)]))}</section>`)};
function editBorrowerCard(id){let p=borrowers.find(x=>x.id===id);formDialog('Thẻ thư viện · '+p.name,inputField('status','Trạng thái',p.card.status,'text',['Hoạt động','Bị khóa'])+inputField('expiry','Ngày hết hạn',p.card.expiry,'date')+inputField('reason','Lý do thay đổi'),v=>{p.card.status=v.status;p.card.expiry=v.expiry;log('Cập nhật thẻ '+id+': '+v.reason)})}
function filterBar(statuses=['Tất cả trạng thái'],types=['Tất cả loại']){return `<div class="filtergrid"><input type="search" aria-label="Tìm trong danh sách" placeholder="Tìm theo mã, tên hoặc nội dung…" oninput="filterList(this)"><select aria-label="Lọc trạng thái" onchange="filterList(this)">${statuses.map(x=>`<option>${x}</option>`).join('')}</select><select aria-label="Lọc loại" onchange="filterList(this)">${types.map(x=>`<option>${x}</option>`).join('')}</select><button onclick="let p=this.closest('.filtergrid');p.querySelector('input').value='';p.querySelectorAll('select').forEach(s=>s.selectedIndex=0);filterList(this)">Xóa bộ lọc</button></div><p class="fineprint listcount" aria-live="polite"></p>`}
function filterList(el){let block=el.closest('.panel'),bar=el.closest('.filtergrid');let terms=[bar.querySelector('input').value,...Array.from(bar.querySelectorAll('select')).map(s=>s.selectedIndex?s.value:'')].filter(Boolean).map(norm),n=0;block.querySelectorAll('tbody tr').forEach(tr=>{tr.hidden=!terms.every(t=>norm(tr.textContent).includes(t));if(!tr.hidden)n++});block.querySelector('.listcount').textContent=n?'Hiển thị '+n+' dòng phù hợp.':'Không có dòng phù hợp. Hãy xóa bớt điều kiện lọc.'}
views.copies=function(){return shell('Bản sao và vị trí','Theo dõi từng cuốn sách vật lý, nhãn nhận diện và khả năng cho mượn.',`<div class="toolbar"><span>${db.copies.length} bản sao</span>${btn('Đăng ký bản sao','newCopy()',true)}</div><section class="panel">${filterBar(['Tất cả trạng thái','Sẵn sàng','Đang mượn','Ngừng phục vụ'])}${table(['Mã cuốn','Tài liệu / Ấn bản','Vị trí cụ thể','Trạng thái','Thao tác'],db.copies.map(c=>[c.code,esc(book(c.book).title)+'<br><small>'+book(c.book).year+'</small>',locationLabel(c.location),badge(c.status,c.status==='Sẵn sàng'?'':'warn'),btn('Chuyển vị trí',`moveCopy(${c.id})`)+btn('Xem nhãn dán sách',`printTag(${c.id})`)+btn('Rút khỏi cho mượn',`withdrawCopy(${c.id})`)]))}</section><div class="note"><strong>Nhãn dán sách:</strong> mã cuốn và ký hiệu giúp nhận diện cuốn sách trên kệ. <strong>Rút khỏi cho mượn:</strong> dùng khi thanh lý hoặc ngừng lưu hành; vẫn giữ bản ghi và lịch sử, không xóa tài liệu.</div>`)};
printTag=function(id){let c=db.copies.find(x=>x.id===id),d=$('#dialog');d.innerHTML=`<h2>Nhãn nhận diện dán lên cuốn sách</h2><p class="muted">Nhãn này dùng để phân biệt từng bản sao. Bản mẫu hiện chưa tạo mã vạch có thể quét.</p><div class="tagpreview"><span>THƯ VIỆN ĐẠI HỌC</span><h3>${esc(book(c.book).title)}</h3><strong>${esc(c.code)}</strong><p>${esc(locationLabel(c.location))}</p></div><div class="actions">${btn('Đóng',"$('#dialog').close()")}${btn('Tải nội dung nhãn',`downloadText('nhan-${c.code}.txt','THU VIEN - ${c.code}')`,true)}</div>`;d.showModal()};
const baseWithdrawal=withdrawCopy;withdrawCopy=function(id){let c=db.copies.find(x=>x.id===id);if(c.status!=='Sẵn sàng')return toast('Chỉ rút bản sẵn sàng, không còn khoản mượn hoặc giữ chỗ.');formDialog('Rút bản sao khỏi danh sách cho mượn',inputField('reason','Lý do rút khỏi phục vụ','','textarea'),v=>{c.status='Ngừng phục vụ';syncCopies();log('Rút '+c.code+' khỏi phục vụ: '+v.reason)},'Xác nhận rút bản sao','Không xóa sách hoặc lịch sử. Dùng cho bản thanh lý / ngừng lưu hành, không dùng thay cho nhận trả.')};
views.reports=function(){syncCopies();let total=db.copies.length,active=borrowers.reduce((s,p)=>s+p.loans.length,0),due=db.fees.reduce((s,f)=>s+amountLeft(f),0),pending=db.approvals.filter(a=>a.status==='Chờ duyệt');let statuses=['Sẵn sàng','Đang mượn','Chờ nhận','Ngừng phục vụ'];return shell('Báo cáo và giám sát','Tổng hợp tại thời điểm hiện tại của phiên mẫu. Chưa có lịch sử đủ để thống kê theo tháng.',`<div class="toolbar"><span class="fineprint">Phạm vi: toàn bộ dữ liệu mẫu · Không có số liệu xu hướng giả lập</span>${btn('Xuất báo cáo CSV','exportDetailedReport()',true)}</div><div class="metricgrid">${[['Bản sao vật lý',total,'Tách riêng khỏi số ấn bản'],['Khoản mượn đang mở',active,'Giao dịch trong phạm vi mẫu'],['Công nợ còn lại',money(due),'Sau thu và miễn giảm'],['Hồ sơ chờ quyết định',pending.length,'Cần quản lý xử lý']].map(([t,n,s])=>`<div class="metric">${t}<strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="reportgrid"><section class="panel"><h2>Tình trạng bản sao</h2><p class="fineprint">${total} bản sao · ${books.filter(b=>b.type==='Sách in').length} ấn bản sách in</p><div class="statuscards">${statuses.map((s,i)=>{let n=db.copies.filter(c=>c.status===s).length;return `<div class="statuscard" style="border-left-color:${['#27694f','#ab7421','#2257aa','#748292'][i]}"><span>${s}</span><strong>${n}</strong><small>${total?Math.round(n*100/total):0}% tổng bản sao</small><div class="progressrail"><i style="width:${total?n*100/total:0}%"></i></div></div>`}).join('')}</div></section><section class="panel"><div class="row"><h2>Hồ sơ cần quyết định</h2>${btn('Mở hàng chờ',"go('approvals')")}</div>${pending.length?pending.slice(0,5).map(a=>`<div class="taskitem"><div><strong>${esc(a.title)}</strong><p>${a.kind}</p></div>${btn('Xem',`decide(${a.id})`)}</div>`).join(''):'<div class="empty">Không có hồ sơ chờ duyệt.</div>'}</section></div><section class="panel" style="margin-top:22px"><h2>Chi tiết khoản mượn theo bạn đọc</h2>${filterBar(['Tất cả trạng thái'],['Tất cả loại'])}${table(['Bạn đọc','Mã cuốn','Tài liệu','Hạn trả','Lượt gia hạn'],borrowers.flatMap(p=>p.loans.map(l=>[p.name+' · '+p.id,l.copyCode||'—',esc(book(l.id).title),l.due,l.renew+'/1'])))}</section><div class="reportgrid" style="margin-top:22px"><section class="panel"><h2>Đối soát khoản phạt</h2>${table(['Chỉ tiêu','Số tiền'],[['Phát sinh',money(db.fees.reduce((s,f)=>s+f.amount,0))],['Đã thu',money(db.fees.reduce((s,f)=>s+f.paid,0))],['Đã miễn giảm',money(db.fees.reduce((s,f)=>s+f.waived,0))],['Còn phải thu',money(due)]] )}</section><section class="panel"><h2>Hồ sơ học liệu số</h2>${table(['Trạng thái','Số hồ sơ'],[...new Set(state.submissions.map(s=>s.status))].map(s=>[s,state.submissions.filter(x=>x.status===s).length]))}</section></div>`)};
function exportDetailedReport(){let rows=[['Nhom','Ma','Ten','Trang thai','Gia tri'],...db.copies.map(c=>['Ban sao',c.code,book(c.book).title,c.status,c.location]),...borrowers.flatMap(p=>p.loans.map(l=>['Khoan muon',p.id,book(l.id).title,'Dang muon',l.due])),...db.fees.map(f=>['Cong no',f.id,f.title,'Con phai thu',amountLeft(f)])];downloadText('bao-cao-chi-tiet.csv','\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n'))}
menus.manager.splice(2,0,['management','Theo dõi xử lý']);
views.management=function(){return shell('Theo dõi xử lý thư viện','Đối chiếu hồ sơ, người phụ trách và kết quả trước khi ra quyết định.',`<section class="panel"><h2>Sự cố và đề xuất</h2>${filterBar(['Tất cả trạng thái','Đang xử lý','Mới tiếp nhận','Cần bổ sung','Đã duyệt phương án','Đã giải quyết'])}${table(['Mã hồ sơ','Nội dung','Loại','Trạng thái','Chi tiết'],db.cases.map(c=>['SC-'+c.id,esc(c.title),c.type,badge(c.status,'blue'),btn('Mở hồ sơ',`managerCase(${c.id})`)]))}</section><section class="panel"><h2>Tiến độ kiểm kê</h2>${table(['Đợt','Khu vực','Đã quét','Trạng thái'],db.stocks.map(s=>[esc(s.title),s.area,s.seen.length,badge(s.status,'blue')]))}</section><section class="panel"><h2>Các quyết định đã ban hành</h2>${table(['Hồ sơ','Loại','Kết quả','Lý do'],db.approvals.filter(a=>a.status!=='Chờ duyệt').map(a=>[esc(a.title),a.kind,badge(a.status,'blue'),esc(a.reason||'—')]))}</section>`)};
function managerCase(id){let c=db.cases.find(x=>x.id===id),d=$('#dialog');d.innerHTML=`<h2>SC-${c.id} · ${esc(c.title)}</h2><dl class="detailsummary"><dt>Loại hồ sơ</dt><dd>${c.type}</dd><dt>Trạng thái</dt><dd>${c.status}</dd><dt>Đơn vị phụ trách</dt><dd>${c.type==='Lỗi tài liệu số'?'Cán bộ học liệu số':'Cán bộ mượn trả / kho'}</dd></dl><h3>Thông tin và bằng chứng ghi nhận</h3><p class="detailtext">${esc(c.detail)}</p><div class="note">Phê duyệt phương án được thực hiện ở hàng chờ. Giao diện này không thay thế công việc xác minh của cán bộ.</div><div class="actions">${btn('Đóng',"$('#dialog').close()")}${btn('Đến hàng chờ',"$('#dialog').close();go('approvals')",true)}</div>`;d.showModal()}
// Add contextual filters to remaining worklists without creating new routes.
const filterSpecs={inventory:[['Tất cả trạng thái','Bản nháp','Chờ duyệt','Đã duyệt','Đã công bố'],['Tất cả loại','Sách in','Tài liệu số','Luận văn']],cases:[['Tất cả trạng thái','Mới tiếp nhận','Đang xử lý','Cần bổ sung','Chờ quản lý duyệt','Đã giải quyết'],['Tất cả loại','Sự cố vật lý','Lỗi tài liệu số','Đề xuất bổ sung']],queue:[['Tất cả trạng thái','Chờ kiểm tra','Cần bổ sung','Đã tiếp nhận','Từ chối'],['Tất cả loại','Luận văn thạc sĩ','Khóa luận tốt nghiệp']],resources:[['Tất cả trạng thái','Chưa công bố','Chờ duyệt','Đã công bố'],['Tất cả loại','Tệp PDF','Liên kết ngoài']],accounts:[['Tất cả trạng thái','Hoạt động','Bị khóa'],['Tất cả loại',...Object.values(roles)]],approvals:[['Tất cả trạng thái','Chờ duyệt','Chấp thuận','Yêu cầu chỉnh sửa','Từ chối'],['Tất cả loại','Bản ghi','Miễn giảm phạt','Công bố số','Phương án sự cố']]};
for(const [route,spec]of Object.entries(filterSpecs)){let fn=views[route];views[route]=()=>{let content=fn();return content.replace('<div class="tablewrap">',filterBar(...spec)+'<div class="tablewrap">')}}
const originalDecision=decide;decide=function(id){originalDecision(id);let a=db.approvals.find(x=>x.id===id),form=$('#dynamicform');let summary=document.createElement('div');summary.className='note';let info=a.kind==='Bản ghi'?`Tác giả: ${a.data.author}\nNăm: ${a.data.year}\nChủ đề: ${a.data.subject}\nTóm tắt: ${a.data.desc}`:a.kind==='Miễn giảm phạt'?`Lý do đề nghị: ${a.data.reason}\nCòn phải thu: ${money(amountLeft(db.fees.find(f=>f.id===a.data.fee)))}`:a.kind==='Công bố số'?`Loại: ${a.data.kind}\nPhiên bản: ${a.data.version}\nQuyền: ${a.data.access}\nCăn cứ: ${a.data.license}`:a.data.detail;summary.textContent=info||'Chưa có thông tin bổ sung';summary.style.whiteSpace='pre-wrap';form.prepend(summary)};
views.transactions=function(){return shell('Khoản mượn và hàng chờ','Tra cứu giao dịch của từng bạn đọc, đến quầy xử lý đúng hồ sơ.',`<section class="panel"><h2>Khoản mượn đang mở</h2>${filterBar()}${table(['Bạn đọc','Mã cuốn','Tài liệu','Hạn trả','Thao tác'],borrowers.flatMap(p=>p.loans.map(l=>[p.name+'<br><small>'+p.id+'</small>',l.copyCode||'—',esc(book(l.id).title),l.due,btn('Xử lý tại quầy',`ux.borrower='${p.id}';state.scanned=[];go('desk')`)])))}</section><section class="panel"><h2>Hàng chờ của bạn đọc mẫu</h2>${filterBar(['Tất cả trạng thái','Chờ sách','Chờ nhận'])}${table(['Tài liệu','Bạn đọc','Trạng thái','Bản sao được giữ','Thao tác'],state.holds.map(h=>[esc(book(h.id).title),'Nguyễn Minh Anh',badge(h.status||'Chờ sách','blue'),h.copyCode||'Chưa phân bổ',btn('Phân bổ bản sao',`allocateHold(${h.id})`)]))}</section>`)};
allocateHold=function(id){let h=state.holds.find(x=>x.id===id);if(!h)return;if(h.copyCode)return toast('Đã có bản sao được giữ.');let c=db.copies.find(c=>c.book===id&&c.status==='Sẵn sàng');if(!c)return toast('Chưa có bản sao sẵn sàng.');h.status='Chờ nhận';h.copyCode=c.code;c.status='Chờ nhận';syncCopies();log('Phân bổ '+c.code+' cho Minh Anh');render();toast('Đã giữ bản sao cho người đặt trước.')};
cancelHold=function(id){let h=state.holds.find(x=>x.id===id);if(!h)return;confirmBox('Hủy đặt trước','Yêu cầu sẽ rời hàng chờ và giải phóng bản sao đã giữ, nếu có.','Hủy đặt trước',()=>{if(h.copyCode){let c=db.copies.find(c=>c.code===h.copyCode);if(c)c.status='Sẵn sàng'}state.holds.splice(state.holds.indexOf(h),1);
syncCopies();render();
toast('Đã hủy đặt trước.')})};
const currentLoansView=views.loans;views.loans=()=>{let html=currentLoansView();state.holds.forEach(h=>{if(h.status==='Chờ nhận')html=html.replace('Đang chờ có sách','Chờ nhận · '+h.copyCode)});return html};
