views.settings=function(){if(session.role!=='manager')return '<div class="wrap"><h2>Bạn không có quyền sửa thiết lập phục vụ.</h2></div>';return shell('Lịch và thiết lập phục vụ','Quản lý thư viện thiết lập điểm phục vụ, thời gian giữ sách và lịch đóng cửa.',`<form class="panel" onsubmit="event.preventDefault();saveServiceSettings(this)"><div class="formgrid">${inputField('branch','Tên điểm phục vụ',db.settings.branch)}${inputField('email','Email liên hệ thư viện',db.settings.email,'email')}${inputField('hold','Số ngày giữ sách chờ nhận',db.settings.hold,'number')}${inputField('closed','Ngày đóng cửa',db.settings.closed,'text',['Chủ nhật','Thứ bảy và Chủ nhật','Không có'])}</div><p class="fineprint" style="margin-top:18px">Thời gian giữ sách là khoảng chờ bạn đọc đến nhận sau khi được phân bổ, không phải thời hạn mượn.</p><div class="actions"><button class="primary">Lưu thiết lập phục vụ</button></div></form><div class="note">Thiết lập được lưu trong phiên mẫu. Chưa tự tính lại hạn nhận, lịch giao dịch hoặc gửi email.</div>`)};
function saveServiceSettings(form){if(session.role!=='manager')return toast('Chỉ quản lý thư viện được thay đổi thiết lập phục vụ.');let values=Object.fromEntries(new FormData(form));if(!Number.isInteger(+values.hold)||+values.hold<1)return toast('Số ngày giữ sách phải là số nguyên từ 1 trở lên.');Object.assign(db.settings,values,{hold:+values.hold});log('Quản lý thư viện cập nhật lịch và thiết lập phục vụ');toast('Đã lưu thiết lập trong phiên mẫu.')}
// Build filters from the actual columns and values of each associated table.
// Exact column matches prevent e.g. "Đã công bố" matching "Chưa công bố" or an action label.
filterBar=function(){return '<div class="filtergrid" data-column-filters></div><p class="fineprint listcount" aria-live="polite"></p>'};
function matchesColumns(row,query,selected){return (!query||row.search.includes(norm(query.trim())))&&Object.entries(selected).every(([column,value])=>!value||row.cells[Number(column)]===value)}
function tableFilterModel(t){let headers=Array.from(t.querySelectorAll('thead th')).map(h=>h.textContent.trim());let excluded=headers.map((h,i)=>!h||/^(Thao tác|Hành động|Chi tiết)$/.test(h)?i:-1).filter(i=>i>=0);let rows=Array.from(t.querySelectorAll('tbody tr')).filter(r=>r.cells.length===headers.length).map(element=>{let cells=Array.from(element.cells).map(c=>c.textContent.trim());return {element,cells,search:norm(cells.filter((_,i)=>!excluded.includes(i)).join(' '))}});let available=['Trạng thái','Hiệu lực','Loại','Vai trò','Đơn vị','Khu vực','Điểm nhận','Cơ sở','Vị trí cụ thể','Truy cập','Kết quả'];let columns=headers.map((label,index)=>({label,index,values:[...new Set(rows.map(r=>{let cell=r.element.cells[index];let badge=cell.querySelector('.badge');return badge?badge.textContent.trim():r.cells[index]}))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'vi'))})).filter(c=>available.includes(c.label));for(let c of columns){for(let row of rows){let badge=row.element.cells[c.index].querySelector('.badge');if(badge)row.cells[c.index]=badge.textContent.trim()}}return {headers,rows,columns}}
function hydrateListFilters(){document.querySelectorAll('[data-column-filters]').forEach(bar=>{let panel=bar.closest('.panel'),t=panel?.querySelector('table');if(!t)return;let model=tableFilterModel(t);bar._filterModel=model;bar.innerHTML=`<label class="field">Tìm trong danh sách<input type="search" aria-label="Tìm trong danh sách" placeholder="Mã, tên hoặc nội dung…"></label>${model.columns.map(c=>`<label class="field">${esc(c.label)}<select data-column="${c.index}" aria-label="Lọc ${esc(c.label)}"><option value="">Tất cả ${esc(c.label.toLowerCase())}</option>${c.values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`).join('')}<button type="button" style="align-self:end">Xóa bộ lọc</button>`;bar.style.gridTemplateColumns=`repeat(${Math.min(model.columns.length+2,4)},minmax(0,1fr))`;bar.querySelector('input').oninput=()=>filterList(bar);bar.querySelectorAll('select').forEach(s=>s.onchange=()=>filterList(bar));bar.querySelector('button').onclick=()=>{bar.querySelector('input').value='';bar.querySelectorAll('select').forEach(s=>s.value='');filterList(bar)};panel.querySelectorAll('.toolbar input[oninput="filterRows(this)"]').forEach(i=>i.remove());filterList(bar)})}
filterList=function(el){let bar=el.matches?.('[data-column-filters]')?el:el.closest('[data-column-filters]');if(!bar||!bar._filterModel)return;let selected=Object.fromEntries(Array.from(bar.querySelectorAll('select')).map(s=>[s.dataset.column,s.value]));let q=bar.querySelector('input').value,n=0;for(let row of bar._filterModel.rows){row.element.hidden=!matchesColumns(row,q,selected);if(!row.element.hidden)n++}let count=bar.parentElement.querySelector('.listcount');if(count)count.textContent=n?`Hiển thị ${n} / ${bar._filterModel.rows.length} dòng.`:'Không có dữ liệu phù hợp. Hãy xóa bớt điều kiện lọc.'};
const renderBeforeColumnFilters=render;
render=function(){renderBeforeColumnFilters();hydrateListFilters()};

// Publication metadata is stored per edition; publishers are shared records.
db.publishers=db.publishers||[];
menus.catalog.push(['publishers','Danh mục nhà xuất bản']);
const editorBeforePublication=views.editor;
views.editor=function(){let b=books.find(x=>x.id===db.editId)||{};let html=editorBeforePublication();let fields=`<div class="full" style="border-top:1px solid var(--line);padding-top:20px"><h3>Thông tin xuất bản</h3><p class="fineprint">Thông tin thuộc ấn bản đang biên mục. Nhà xuất bản được quản lý trong menu Danh mục nhà xuất bản.</p></div><label class="field">Nhà xuất bản<select name="publisherId"><option value="">Chưa xác định</option>${db.publishers.map(p=>`<option value="${esc(p.id)}" ${p.id===b.publisherId?'selected':''}>${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></label>${inputField('publicationPlace','Nơi xuất bản',b.publicationPlace||'').replace(' required','')}${inputField('language','Ngôn ngữ (ví dụ: Tiếng Việt; Tiếng Anh)',b.language||'').replace(' required','')}${inputField('edition','Lần xuất bản / thông tin tái bản',b.edition||'').replace(' required','')}<div class="full fineprint">Có thể ghi nhiều ngôn ngữ cho sách song ngữ. Địa chỉ liên hệ được lưu tại danh mục nhà xuất bản.</div>`;return html.replace('<div class="actions"><button type="button" onclick="go(\'inventory\')">',fields+'</div><div class="actions"><button type="button" onclick="go(\'inventory\')">').replace('</textarea></label></div></div><div class="full"','</textarea></label></div><div class="full"')};
views.publishers=function(){return shell('Danh mục nhà xuất bản','Dùng chung cho các ấn bản. Mã nhà xuất bản được tạo tự động.',`<section class="panel"><div class="row"><h2>Nhà xuất bản</h2>${btn('Thêm nhà xuất bản','editPublisher()',true)}</div>${filterBar()}${table(['Mã nhà xuất bản','Tên nhà xuất bản','Địa chỉ liên hệ','Thao tác'],db.publishers.map(p=>[esc(p.id),esc(p.name),esc(p.address||'Chưa bổ sung'),btn('Chỉnh sửa',`editPublisher('${p.id}')`)]))}<p class="fineprint">Thêm nhà xuất bản tại đây trước khi chọn trong biểu mẫu biên mục.</p></section>`)};
function editPublisher(id){if(session.role!=='catalog')return;let p=db.publishers.find(x=>x.id===id)||{};formDialog(p.id?'Chỉnh sửa nhà xuất bản':'Thêm nhà xuất bản',inputField('name','Tên nhà xuất bản',p.name||'')+inputField('address','Địa chỉ liên hệ',p.address||'','textarea').replace(' required',''),v=>{let name=v.name.trim();if(!name)throw Error('Nhập tên nhà xuất bản.');if(db.publishers.some(x=>x.id!==id&&norm(x.name)===norm(name)))throw Error('Nhà xuất bản này đã có trong danh mục.');if(p.id)Object.assign(p,{name,address:v.address.trim()});else db.publishers.push({id:'NXB-'+String(db.publishers.length+1).padStart(3,'0'),name,address:v.address.trim()});log('Cập nhật danh mục nhà xuất bản: '+name)},'Lưu nhà xuất bản')}
const detailBeforePublication=views.detail;
views.detail=function(){let html=detailBeforePublication(),b=book(state.selected),p=db.publishers.find(x=>x.id===b.publisherId);let info=`<section class="wrap" style="margin-top:24px"><div class="panel"><h2>Thông tin xuất bản</h2><dl class="detailsummary"><dt>Nhà xuất bản</dt><dd>${esc(p?.name||'Chưa bổ sung')}</dd><dt>Nơi xuất bản</dt><dd>${esc(b.publicationPlace||'Chưa bổ sung')}</dd><dt>Năm xuất bản</dt><dd>${esc(String(b.year||'Chưa bổ sung'))}</dd><dt>Lần xuất bản</dt><dd>${esc(b.edition||'Chưa bổ sung')}</dd><dt>Ngôn ngữ</dt><dd>${esc(b.language||'Chưa bổ sung')}</dd><dt>ISBN</dt><dd>${esc(b.isbn||'Chưa bổ sung')}</dd></dl></div></section>`;return html+info};


// Priority fixes: explicit demo credentials and calendar-based overdue workflow.
const demoPasswords=new Map();
Object.keys(roles).forEach(role=>{if(!db.accounts.some(a=>a.role===role))db.accounts.push({id:db.accounts.length+1,name:roles[role],email:role+'@example.edu',role,status:'Hoạt động'})});
views.login=function(){return `<div class="wrap" style="max-width:620px"><section class="panel"><h1>Đăng nhập thư viện</h1><p class="note">Mô phỏng frontend, chưa xác thực máy chủ. Chỉ dùng dữ liệu mẫu; không nhập mật khẩu thật.</p><form onsubmit="event.preventDefault();passwordLogin(this)">${inputField('email','Email tài khoản mẫu','minhanh@example.edu','email')}${inputField('password','Mật khẩu mẫu','','password')}<p class="fineprint">Mật khẩu ban đầu của tài khoản mẫu: Demo@12345</p><p id="loginerror" role="alert" class="error"></p><button class="primary">Đăng nhập</button></form><button class="link" onclick="forgotPassword()">Quên mật khẩu</button><details style="margin-top:20px"><summary>Tài khoản để thử từng vai trò</summary>${db.accounts.map(a=>`<p>${esc(roles[a.role])}: <strong>${esc(a.email)}</strong>${a.mustChangePassword?' · Cần đổi mật khẩu lần đầu':''}</p>`).join('')}</details><button class="link" onclick="session.pendingAccount=null;go('search')">Tra cứu với tư cách khách</button></section></div>`};
function passwordLogin(form){let v=Object.fromEntries(new FormData(form)),a=db.accounts.find(x=>x.email.toLowerCase()===v.email.trim().toLowerCase());if(!a||a.status!=='Hoạt động'||v.password!==(demoPasswords.get(a.id)||'Demo@12345')){$('#loginerror').textContent='Email, mật khẩu không đúng hoặc tài khoản đã bị khóa.';return}session.role=null;session.accountId=null;session.pendingAccount=a.mustChangePassword?a.id:null;if(session.pendingAccount)return go('password');session.role=a.role;session.accountId=a.id;go(a.role==='reader'?'home':'work')}
function forgotPassword(){formDialog('Quên mật khẩu',inputField('email','Email tài khoản mẫu','','email'),()=>{toast('Đã mô phỏng yêu cầu khôi phục. Chưa gửi email và chưa đổi mật khẩu.')},'Mô phỏng yêu cầu','Bản mẫu không gửi email hoặc tạo liên kết đặt lại mật khẩu. Khi triển khai cần máy chủ xác minh yêu cầu.')}
views.password=function(){return `<div class="wrap" style="max-width:620px"><form class="panel" onsubmit="event.preventDefault();changeDemoPassword(this)"><h1>${session.pendingAccount?'Đổi mật khẩu lần đầu':'Đổi mật khẩu'}</h1><p class="note">Chỉ thử bằng mật khẩu giả. Thay đổi có hiệu lực trong phiên mẫu này.</p>${inputField('current','Mật khẩu hiện tại','','password')}${inputField('next','Mật khẩu mới (ít nhất 8 ký tự)','','password')}${inputField('confirm','Nhập lại mật khẩu mới','','password')}<p id="passworderror" class="error" role="alert"></p><button class="primary">Lưu mật khẩu mới</button><button type="button" onclick="session.pendingAccount=null;session.role=null;session.accountId=null;go('login')">Đăng xuất</button></form></div>`};
function changeDemoPassword(form){let v=Object.fromEntries(new FormData(form)),a=db.accounts.find(x=>x.id===(session.pendingAccount||session.accountId));if(!a||v.current!==(demoPasswords.get(a.id)||'Demo@12345')||v.next.length<8||v.next!==v.confirm||v.next===v.current){$('#passworderror').textContent='Kiểm tra mật khẩu hiện tại; mật khẩu mới phải khác, đủ 8 ký tự và khớp xác nhận.';return}demoPasswords.set(a.id,v.next);a.mustChangePassword=false;session.pendingAccount=null;session.accountId=a.id;session.role=a.role;go('profile');toast('Đã đổi mật khẩu mẫu trong phiên.')}
Object.values(menus).forEach(menu=>{if(!menu.some(([page])=>page==='profile'))menu.push(['profile','Hồ sơ cá nhân'])});
function libraryToday(){let parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());let get=t=>parts.find(p=>p.type===t).value;return get('year')+'-'+get('month')+'-'+get('day')}
function overdueDays(due,today=libraryToday()){let a=due.split('/').map(Number);if(a.length!==3)return 0;let stamp=Date.UTC(a[2],a[1]-1,a[0]);return Math.max(0,Math.floor((Date.parse(today+'T00:00:00Z')-stamp)/86400000))||0}
db.reminders=[];
menus.circulation.push(['overdue','Sách quá hạn']);
views.overdue=function(){let rows=borrowers.flatMap(p=>p.loans.filter(l=>overdueDays(l.due)>0).map(l=>[esc(p.name)+' · '+esc(p.id),esc(l.copyCode||book(l.id).code),esc(book(l.id).title),esc(l.due),overdueDays(l.due)+' ngày',btn('Tạo nhắc hạn mẫu',`remindOverdue('${p.id}',${l.id})`)]));return shell('Sách quá hạn','Tính theo ngày hiện tại tại Việt Nam: '+libraryToday(),`<section class="panel"><p class="note">Nhắc hạn chỉ tạo thông báo trong phiên mẫu. Chưa gửi email hoặc chạy lịch tự động. Không tự phát sinh tiền phạt.</p>${filterBar()}${table(['Bạn đọc','Mã cuốn','Tài liệu','Hạn trả','Quá hạn','Thao tác'],rows)}</section>`)};
function remindOverdue(pid,id){if(session.role!=='circulation')return;let p=borrowers.find(x=>x.id===pid),l=p?.loans.find(x=>x.id===id);if(!l||!overdueDays(l.due))return toast('Khoản mượn không còn quá hạn.');if(db.reminders.some(r=>r.pid===pid&&r.id===id&&r.date===libraryToday()))return toast('Đã tạo nhắc hạn cho khoản mượn này hôm nay.');db.reminders.push({pid,id,date:libraryToday(),text:'Sách “'+book(id).title+'” quá hạn '+overdueDays(l.due)+' ngày. Vui lòng liên hệ quầy mượn trả.'});log('Tạo nhắc hạn mẫu cho '+pid);toast('Đã tạo thông báo mẫu. Chưa gửi email.')}
const loansBeforeOverdue=views.loans;
views.loans=function(){let html=loansBeforeOverdue();for(let l of state.loans){let n=overdueDays(l.due);if(n)html=html.replace(l.due+'<br>'+badge('Đang mượn','blue'),esc(l.due)+'<br>'+badge('Quá hạn '+n+' ngày','warn'))}return html};
const notificationsBeforeOverdue=views.notifications;
views.notifications=function(){let html=notificationsBeforeOverdue();if(session.role==='reader')html+=`<section class="wrap"><div class="panel"><h2>Nhắc hạn mượn sách</h2><p class="fineprint">Thông báo mẫu trong ứng dụng; chưa gửi email.</p>${db.reminders.filter(r=>r.pid==='SV20240018').map(r=>`<p>${esc(r.date)} · ${esc(r.text)}</p>`).join('')||'<p>Chưa có nhắc hạn được tạo.</p>'}</div></section>`;return html};

// Profile, card photo and password share one personal-account destination.
function signedInAccount(){return db.accounts.find(a=>a.id===session.accountId)}
views.profile=function(){let a=signedInAccount();if(!a)return '<div class="wrap"><p>Đăng nhập để xem hồ sơ cá nhân.</p></div>';let isReader=a.role==='reader',contact=a.contact||{},name=a.name,photo=a.photoUrl;return shell(isReader?'Hồ sơ & thẻ':'Hồ sơ cá nhân','Cập nhật thông tin liên hệ, ảnh và bảo mật tài khoản.',`<div class="reportgrid"><section class="panel"><h2>${isReader?'Ảnh thẻ thư viện':'Ảnh hồ sơ'}</h2><div style="display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:20px 0"><div style="width:120px;height:160px;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:var(--pale);display:grid;place-items:center">${photo?`<img src="${esc(photo)}" alt="Ảnh hồ sơ của ${esc(name)}" style="width:100%;height:100%;object-fit:cover">`:'<span class="muted">Chưa có ảnh</span>'}</div><div><strong>${esc(name)}</strong><p>${esc(roles[a.role])}</p><label class="field">Chọn ảnh mới<input type="file" accept="image/jpeg,image/png,image/webp" onchange="updateProfilePhoto(this)"></label>${photo?btn('Gỡ ảnh','removeProfilePhoto()'):''}</div></div><p class="fineprint">JPG, PNG hoặc WebP, tối đa 2 MB. Ảnh chỉ được giữ trong phiên xem này, chưa tải lên máy chủ.</p>${isReader?`<hr><h3>Thẻ thư viện</h3>${a.id===1?`<p>LIB-20240018 · SV20240018</p>${badge(db.card.status)}<p>Hạn thẻ: ${esc(db.card.expiry)}</p>`:'<p>Chưa liên kết thẻ thư viện.</p>'}<p class="fineprint">Mã thẻ, hiệu lực và hạn thẻ do cán bộ thư viện quản lý.</p>`:''}</section><section class="panel"><h2>Thông tin cá nhân</h2><p><strong>Họ tên:</strong> ${esc(name)}</p><p><strong>Email đăng nhập:</strong> ${esc(a.email)}</p><form onsubmit="event.preventDefault();savePersonalProfile(this)">${inputField('email','Email liên hệ',contact.email||(a.id===1?db.card.email:a.email),'email')}${inputField('phone','Số điện thoại',contact.phone||(a.id===1?db.card.phone:''),'tel').replace(' required','')}<div class="actions"><button class="primary">Lưu hồ sơ</button></div></form><p class="fineprint">Để sửa họ tên hoặc email đăng nhập, liên hệ quản trị viên.</p></section></div><section class="panel" style="margin-top:24px"><h2>Bảo mật tài khoản</h2><p>Đổi mật khẩu trong hồ sơ cá nhân.</p><details><summary>Đổi mật khẩu</summary><form style="max-width:560px;margin-top:18px" onsubmit="event.preventDefault();changeDemoPassword(this)"><p class="fineprint">Chỉ dùng mật khẩu giả; thay đổi có hiệu lực trong phiên mẫu.</p>${inputField('current','Mật khẩu hiện tại','','password')}${inputField('next','Mật khẩu mới (ít nhất 8 ký tự)','','password')}${inputField('confirm','Nhập lại mật khẩu mới','','password')}<p id="passworderror" class="error" role="alert"></p><button class="primary">Lưu mật khẩu mới</button></form></details></section>`)};
function savePersonalProfile(form){let a=signedInAccount();if(!a)return;let v=Object.fromEntries(new FormData(form));a.contact={email:v.email.trim(),phone:v.phone.trim()};if(a.id===1)Object.assign(db.card,a.contact);log('Cập nhật liên hệ cá nhân');toast('Đã lưu hồ sơ trong phiên mẫu.')}
function validProfilePhoto(file){return file&&['image/jpeg','image/png','image/webp'].includes(file.type)&&file.size>0&&file.size<=2*1024*1024}
function updateProfilePhoto(input){let a=signedInAccount(),file=input.files?.[0];if(!a||!file)return;if(!validProfilePhoto(file)){input.value='';return toast('Chọn ảnh JPG, PNG hoặc WebP không quá 2 MB.')}let url=URL.createObjectURL(file),preview=new Image();preview.onload=()=>{if(signedInAccount()?.id!==a.id){URL.revokeObjectURL(url);return}if(a.photoUrl)URL.revokeObjectURL(a.photoUrl);a.photoUrl=url;render();toast('Đã cập nhật ảnh trong phiên mẫu.')};preview.onerror=()=>{URL.revokeObjectURL(url);input.value='';toast('Không đọc được ảnh. Hãy chọn tệp ảnh hợp lệ.')};preview.src=url}
function removeProfilePhoto(){let a=signedInAccount();if(!a?.photoUrl)return;URL.revokeObjectURL(a.photoUrl);delete a.photoUrl;render();toast('Đã gỡ ảnh hồ sơ.')}
syncCopies();render();

